<?php
if(!$PCC->tableExists('rp_phones')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-mobile-alt"></i><strong>ParadisePhone V1 indisponible</strong><span>rp_phones n’existe pas dans cette base.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$status=strtoupper(trim((string)($_GET['status']??'')));$where=array('1=1');$types='';$params=array();$char=$PCC->tableExists('rp_characters');$contacts=$PCC->tableExists('rp_phone_contacts');$messages=$PCC->tableExists('play_phone_chats');$calls=$PCC->tableExists('rp_phone_calls');$joins=' INNER JOIN users u ON u.id=p.user_id'.($char?' LEFT JOIN rp_characters c ON c.user_id=u.id':'');$select='p.id,p.user_id,p.phone_number,p.device_identifier,p.status,p.created_at,p.updated_at,u.username,u.look,u.online'.($char?',c.first_name,c.last_name,c.citizen_id':',NULL first_name,NULL last_name,NULL citizen_id');if($q!==''){$like='%'.mb_substr($q,0,64).'%';$bits=array('p.phone_number LIKE ?','u.username LIKE ?','CAST(u.id AS CHAR)=?');$types.='sss';$params=array($like,$like,$q);if($char){$bits[]='c.citizen_id LIKE ?';$bits[]="CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,'')) LIKE ?";$types.='ss';$params[]=$like;$params[]=$like;}$where[]='('.implode(' OR ',$bits).')';}if($status!==''&&preg_match('/^[A-Z_]{2,20}$/',$status)){$where[]='UPPER(p.status)=?';$types.='s';$params[]=$status;}$rows=$DB->PreparedAll('SELECT '.$select.' FROM rp_phones p'.$joins.' WHERE '.implode(' AND ',$where).' ORDER BY p.id DESC LIMIT 300',$types,$params);
foreach($rows as &$r){$pid=(int)$r['id'];$uid=(int)$r['user_id'];$r['contacts']=0;$r['unread']=0;$r['messages']=0;$r['calls']=0;$r['last_activity']=$r['updated_at'];if($contacts){$x=$DB->PreparedRow('SELECT COUNT(*) c FROM rp_phone_contacts WHERE phone_id=?','i',array($pid));$r['contacts']=$x?(int)$x['c']:0;}if($messages){$hasRead=$PCC->columnExists('play_phone_chats','read_at');$x=$DB->PreparedRow('SELECT COUNT(*) c,MAX(timestamp) last_at FROM play_phone_chats WHERE type=1 AND (emisor_id=? OR receptor_id=?)','ii',array($uid,$uid));if($x){$r['messages']=(int)$x['c'];if($x['last_at'])$r['last_activity']=$x['last_at'];}if($hasRead){$x=$DB->PreparedRow('SELECT COUNT(*) c FROM play_phone_chats WHERE type=1 AND receptor_id=? AND read_at IS NULL','i',array($uid));$r['unread']=$x?(int)$x['c']:0;}}if($calls){$x=$DB->PreparedRow('SELECT COUNT(*) c FROM rp_phone_calls WHERE caller_phone_id=? OR receiver_phone_id=?','ii',array($pid,$pid));$r['calls']=$x?(int)$x['c']:0;}}
unset($r);
?>
<section class="pcc-alert info"><i class="fas fa-user-lock"></i><div><strong>Confidentialité par défaut</strong><p>Cette page expose numéro, propriétaire et statistiques opérationnelles. Le corps des SMS n’est jamais chargé ici. La permission <code>phone.messages.read</code> reste réservée au rank le plus élevé et devra déclencher un audit spécifique si une vue légale/nécessaire est ajoutée.</p></div></section>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="phones"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Numéro, username, Citizen ID…"></div><select name="status" class="pcc-select-compact"><option value="">Tous statuts</option><?php foreach(array('ACTIVE','SUSPENDED','DISABLED') as $s):?><option <?php echo $status===$s?'selected':'';?>><?php echo $s;?></option><?php endforeach;?></select><button class="pcc-button secondary">Filtrer</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> téléphone(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Numéro</th><th>Propriétaire</th><th>Nom RP</th><th>Citizen ID</th><th>Statut</th><th>Contacts</th><th>SMS</th><th>Non lus</th><th>Appels</th><th>Dernière activité</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="11"><div class="pcc-empty compact"><strong>Aucun téléphone trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):$rp=trim((string)$r['first_name'].' '.(string)$r['last_name']);?><tr><td><code><?php echo $h($r['phone_number']);?></code></td><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['user_id'];?> · <?php echo (int)$r['online']===1?'en ligne':'hors ligne';?></small></span></div></td><td><?php echo $rp!==''?$h($rp):'—';?></td><td><code><?php echo $r['citizen_id']?$h($r['citizen_id']):'—';?></code></td><td><span class="pcc-badge <?php echo strtoupper($r['status'])==='ACTIVE'?'success':'warning';?>"><?php echo $h($r['status']);?></span></td><td><?php echo (int)$r['contacts'];?></td><td><?php echo (int)$r['messages'];?></td><td><?php echo (int)$r['unread'];?></td><td><?php echo (int)$r['calls'];?></td><td><?php echo $r['last_activity']?$h($PCC->formatDate($r['last_activity'])):'—';?></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$r['user_id'];?>&tab=phone">Ouvrir</a></td></tr><?php endforeach;?></tbody></table></div></section>
